"""Generate reproducible summary CSVs, executive Markdown, and PDF report."""
from pathlib import Path
from datetime import datetime, timezone
import pandas as pd, numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.lib import colors
from reportlab.lib.pagesizes import letter, landscape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak
from reportlab.lib.styles import getSampleStyleSheet
ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data/processed'; OUT=ROOT/'reports'; OUT.mkdir(exist_ok=True)
f=pd.read_csv(DATA/'fact_sales_clean.csv',parse_dates=['OrderDate']); p=pd.read_csv(DATA/'dim_product.csv'); f=f.merge(p[['ProductID','ProductName','Category','Subcategory']],on='ProductID',how='left')
f['GrossRevenueBeforeDiscount']=f.Quantity*f.UnitListPrice; f['DiscountAmount']=f.Quantity*(f.UnitListPrice-f.UnitSellingPrice)
category=f.groupby('Category').agg(Revenue=('SalesRevenue','sum'),GrossProfit=('GrossProfit','sum'),Units=('Quantity','sum'),ListValue=('GrossRevenueBeforeDiscount','sum'),Discount=('DiscountAmount','sum')).reset_index(); category['MarginPct']=category.GrossProfit/category.Revenue; category['WeightedDiscountPct']=category.Discount/category.ListValue; category=category.sort_values('Revenue',ascending=False); category.to_csv(OUT/'category_performance.csv',index=False)
product=f.groupby(['ProductID','ProductName','Category']).agg(Revenue=('SalesRevenue','sum'),GrossProfit=('GrossProfit','sum'),COGS=('CostOfGoodsSold','sum'),Units=('Quantity','sum'),DiscountAmount=('DiscountAmount','sum'),ListValue=('GrossRevenueBeforeDiscount','sum'),AvgDiscount=('DiscountPct','mean')).reset_index(); product['MarginPct']=product.GrossProfit/product.Revenue; product['WeightedDiscountPct']=product.DiscountAmount/product.ListValue
product['ReviewReason']=np.select([product.MarginPct<.15,product.WeightedDiscountPct>.30,product.GrossProfit<0],['Margin below 15%','Weighted discount above 30%','Negative gross profit'],'Monitor'); exceptions=product[product.ReviewReason!='Monitor'].sort_values(['MarginPct','Revenue']); exceptions.to_csv(OUT/'pricing_exceptions.csv',index=False)
f['YearMonth']=f.OrderDate.dt.to_period('M').astype(str); monthly=f.groupby('YearMonth').agg(Revenue=('SalesRevenue','sum'),GrossProfit=('GrossProfit','sum'),Units=('Quantity','sum'),ListValue=('GrossRevenueBeforeDiscount','sum'),Discount=('DiscountAmount','sum')).reset_index(); monthly['MarginPct']=monthly.GrossProfit/monthly.Revenue; monthly['WeightedDiscountPct']=monthly.Discount/monthly.ListValue; monthly.to_csv(OUT/'monthly_performance.csv',index=False)
f['DiscountBand']=pd.cut(f.DiscountPct,[-.000001,0,.05,.10,.20,.30,1],labels=['0%','>0-5%','>5-10%','>10-20%','>20-30%','>30%'],include_lowest=True)
disc=f.groupby('DiscountBand',observed=False).agg(Revenue=('SalesRevenue','sum'),GrossProfit=('GrossProfit','sum'),Units=('Quantity','sum'),ListValue=('GrossRevenueBeforeDiscount','sum'),Discount=('DiscountAmount','sum')).reset_index(); disc['MarginPct']=disc.GrossProfit/ disc.Revenue.replace(0,np.nan); disc['WeightedDiscountPct']=disc.Discount/disc.ListValue.replace(0,np.nan); disc.to_csv(OUT/'discount_band_performance.csv',index=False)
# visuals used in PDF only; not represented as dashboard screenshots
fig,ax=plt.subplots(figsize=(9,3.5)); ax.bar(category.Category,category.Revenue); ax.set_title('Net sales revenue by category (synthetic data)'); ax.set_ylabel('Revenue'); ax.tick_params(axis='x',rotation=35); fig.tight_layout(); chart=OUT/'category_revenue_chart.png'; fig.savefig(chart,dpi=150); plt.close(fig)
period=f'{f.OrderDate.min().date()} to {f.OrderDate.max().date()}'; total_rev=f.SalesRevenue.sum(); total_profit=f.GrossProfit.sum(); total_margin=total_profit/total_rev; weighted_discount=f.DiscountAmount.sum()/f.GrossRevenueBeforeDiscount.sum()
top_rev=category.iloc[0]; top_profit=category.loc[category.GrossProfit.idxmax()]; weakest=product.nsmallest(5,'MarginPct'); deep=disc[disc.DiscountBand=='>30%'].iloc[0]
findings=[f"{top_rev.Category} has the highest observed revenue at {top_rev.Revenue:,.2f} ({top_rev.Revenue/total_rev:.1%} of all revenue).",f"{top_profit.Category} contributes the highest category gross profit at {top_profit.GrossProfit:,.2f}.",f"Overall gross margin is {total_margin:.1%}; weighted average discount is {weighted_discount:.1%}.",f"The >30% discount band records revenue {deep.Revenue:,.2f}, gross profit {deep.GrossProfit:,.2f}, and margin {deep.MarginPct:.1%}; this is descriptive, not causal evidence.",f"{len(exceptions)} products are flagged by the transparent screening rules (margin below 15%, weighted discount above 30%, or negative gross profit)."]
summary=f'''# Executive Summary — Pricing Optimization Dashboard\n\n**Generated:** {datetime.now(timezone.utc).isoformat()}  \n**Period:** {period}  \n**Data:** synthetic, seed 20261028; findings are illustrative only.\n\n## KPI snapshot\n\n- Net sales revenue: **{total_rev:,.2f}**\n- Gross profit: **{total_profit:,.2f}**\n- Gross margin: **{total_margin:.2%}**\n- Weighted average discount: **{weighted_discount:.2%}**\n- Units sold: **{f.Quantity.sum():,}**\n- Distinct orders: **{f.OrderID.nunique():,}** (the generated grain uses one line per order)\n\n## Findings calculated from this run\n\n'''+''.join(f'{i}. {x}\n' for i,x in enumerate(findings,1))+'''\n## Recommended investigations\n\n1. Review flagged products with adequate unit volume first; a low-volume flag should be treated as weak evidence.\n2. Compare discount bands within the same product/category/channel and use controlled tests before attributing demand changes to discounts.\n3. Check unit costs and list prices against current approved master data before taking pricing action.\n4. Investigate below-cost sales for clearance, bundles, promotions, or data defects before raising prices.\n\n## Limitations\n\nSynthetic observational data cannot establish causal discount elasticity or actual commercial impact. Gross profit excludes shipping, returns, taxes, payment fees, marketing, and other operating costs; it is not net profit. Competitor prices are not verified in this dataset. Currency is illustrative.\n'''
(OUT/'executive_summary.md').write_text(summary)
(OUT/'pricing_recommendations.md').write_text('# Pricing Review Recommendations\n\nThese are screening hypotheses generated from synthetic data, not approved price changes.\n\n'+''.join(f'- **{row.ProductName} ({row.Category})** — revenue {row.Revenue:,.2f}; gross profit {row.GrossProfit:,.2f}; margin {row.MarginPct:.1%}; weighted discount {row.WeightedDiscountPct:.1%}. Reason: {row.ReviewReason}. Validate demand, inventory, strategic role, cost freshness, and data quality before action.\n' for row in exceptions.head(30).itertuples())+'\nDo not infer that discounts caused the observed performance. Run matched or randomized tests where feasible.\n')
styles=getSampleStyleSheet(); pdf=SimpleDocTemplate(str(OUT/'sample_report.pdf'),pagesize=landscape(letter),rightMargin=32,leftMargin=32,topMargin=28,bottomMargin=28); story=[Paragraph('Pricing Optimization & Profitability Intelligence',styles['Title']),Paragraph(f'Synthetic-data executive report | {period} | generated {datetime.now(timezone.utc).isoformat()}',styles['Normal']),Spacer(1,12)]
rows=[['Metric','Value'],['Net sales revenue',f'{total_rev:,.2f}'],['Gross profit',f'{total_profit:,.2f}'],['Gross margin',f'{total_margin:.2%}'],['Weighted average discount',f'{weighted_discount:.2%}'],['Units sold',f'{f.Quantity.sum():,}'],['Product exception flags',str(len(exceptions))]]
t=Table(rows,colWidths=[220,160]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17324D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.4,colors.grey),('PADDING',(0,0),(-1,-1),6)])); story += [t,Spacer(1,12),Image(str(chart),width=620,height=240),PageBreak(),Paragraph('Key findings and recommendations',styles['Heading1'])]
for x in findings: story += [Paragraph('• '+x,styles['BodyText']),Spacer(1,7)]
story += [Spacer(1,8),Paragraph('Caution: Synthetic, observational data only. Gross profit excludes operating costs, taxes, returns and shipping. Discount associations are not causal effects.',styles['Italic'])]; pdf.build(story)
print(f'Generated reports: {OUT}; revenue={total_rev:.2f}; gross_profit={total_profit:.2f}; margin={total_margin:.4f}; flagged_products={len(exceptions)}')
